import {euro,fieldMoney,money,monthName,shiftMonth,validMonth} from './planner.js';
import {defaultTimeline,buildTimeline,applyTimeline,undoTimeline} from './timeline.js';
export function createTimelineUI(ctx){
 const {esc,btn}=ctx,close=()=>document.querySelector('#dialog').close(),cfg=()=>ctx.state.timeline||defaultTimeline(ctx.month);
 const foot=text=>`<div class="form-footer"><button class="btn btn-outline" type="button" data-action="close">Abbrechen</button><button class="btn btn-primary" type="submit">${text}</button></div>`;
 function form(title,html,handler){const revision=ctx.state.revision;ctx.openDialog(title,`<form>${html}</form>`,f=>{if(revision!==ctx.state.revision)throw Error('Der Stand hat sich geändert. Bitte erneut öffnen.');handler(new FormData(f));});}
 function settings(){const c=cfg();if(c.applied)throw Error('Bitte den übernommenen Zeitplan zuerst zurücknehmen.');form('Gemeinsamen Sparrahmen festlegen',`<div class="form-grid"><label><span>Beginn</span><input name="start" type="month" value="${c.start}" min="2000-01" max="2100-12" required></label><label><span>Maximal neu verteilen / Monat (€)</span><input name="cap" inputmode="decimal" value="${fieldMoney(c.cap)}" required></label><label><span>Mindestens frei / Monat (€)</span><input name="minFree" inputmode="decimal" value="${fieldMoney(c.minFree)}" required></label></div><p class="helper spaced">Der Zeitplan verteilt höchstens diesen Betrag, soweit nach bestehenden Posten und Deinem Mindestpuffer Geld frei bleibt. 0 € erstellt nur einen Vergleich. Nicht ausgewählte Sparraten laufen zusätzlich weiter.</p><h3 class="spaced">Diese Sparraten darf der Zeitplan ersetzen</h3><p class="helper">Nur ausgewählte Serien werden bei Übernahme ab dem Start beendet. Bereits angesparte Beträge bleiben in ihren Töpfen.</p>${ctx.state.items.filter(i=>i.type==='saving'&&(!i.end||i.end>=c.start)).map(i=>`<label class="scenario-check"><input type="checkbox" name="replaceIds" value="${i.id}" ${c.replaceIds.includes(i.id)?'checked':''}><span>${esc(i.title)} · ${euro(i.amount)}</span></label>`).join('')||'<p class="helper">Keine Sparraten vorhanden.</p>'}<h3 class="spaced">Geschützte Bestände</h3><p class="helper">Geld unter dieser Grenze steht nicht für einen Wunsch zur Verfügung.</p>${ctx.state.pots.map(p=>`<div class="scenario-protection"><label class="scenario-check"><input type="checkbox" name="protected" value="${p.id}" ${c.protected.some(x=>x.potId===p.id)?'checked':''}><span>${esc(p.name)}</span></label><label><span>Mindestbestand (€)</span><input name="floor_${p.id}" inputmode="decimal" value="${fieldMoney(c.protected.find(x=>x.potId===p.id)?.minimum||0)}"></label></div>`).join('')}${foot('Rahmen speichern')}`,fd=>{const n=structuredClone(ctx.state);n.timeline={start:fd.get('start'),cap:money(fd.get('cap')),minFree:money(fd.get('minFree')),replaceIds:fd.getAll('replaceIds'),protected:fd.getAll('protected').map(potId=>({potId,minimum:money(fd.get('floor_'+potId))}))};if(ctx.persist(n,'Sparrahmen gespeichert'))close();});}
 function editGoal(id){const g=ctx.state.goals.find(g=>g.id===id),s=g.schedule||{priority:50,timing:'flexible',rate:0};if(cfg().applied)throw Error('Bitte den Zeitplan zuerst zurücknehmen.');form('Zeitplan · '+g.title,`<div class="form-grid"><label><span>Priorität · 1 ist am höchsten</span><input name="priority" type="number" min="1" max="1000" value="${s.priority}" required></label><label><span>Wunschmonat</span><input name="deadline" type="month" min="2000-01" max="2100-12" value="${g.deadline||''}"></label><label><span>Termin</span><select name="timing"><option value="flexible" ${s.timing==='flexible'?'selected':''}>Verschiebbar</option><option value="fixed" ${s.timing==='fixed'?'selected':''}>Fest · zuerst berücksichtigen</option></select></label><label><span>Feste neue Rate / Monat (€)</span><input name="rate" inputmode="decimal" value="${fieldMoney(s.rate)}" required></label></div><p class="helper spaced">0 € bedeutet automatische Verteilung. Eine feste Rate gilt bis zur Deckung, soweit Dein gemeinsamer Sparrahmen reicht. Feste Termine werden zuerst bedient, danach Priorität und Wunschdatum. Bereits bestehende Sparraten zählen zusätzlich, sofern Du sie nicht zum Ersetzen freigibst.</p>${foot('Wunsch einordnen')}`,fd=>{const n=structuredClone(ctx.state),x=n.goals.find(g=>g.id===id);x.deadline=fd.get('deadline')||'';x.schedule={priority:Number(fd.get('priority')),timing:fd.get('timing'),rate:money(fd.get('rate'))};if(x.schedule.timing==='fixed'&&!x.deadline)throw Error('Bitte einen Monat für den festen Termin wählen.');if(ctx.persist(n,'Wunsch eingeordnet'))close();});}
 function render(){const c=cfg();if(c.applied)return `<section class="scenario-detail"><span class="goal-kicker">Im Monatsplan</span><h2>Dein gemeinsamer Zeitplan ist übernommen</h2><p class="helper spaced">Die vorgeschlagenen Sparbeträge stehen jetzt als einzelne Monatsraten im Budget. Vorhandene Töpfe wurden nicht umgebucht. Für eine neue Berechnung nimm zuerst diesen Plan zurück; zwischenzeitlich bearbeitete Posten bleiben geschützt.</p>${btn('Übernahme zurücknehmen','timeline-undo','outline','undo')}</section>`;let r;try{r=buildTimeline(ctx.state,c);}catch(e){return `<div class="notice error">${esc(e.message)}</div>${btn('Rahmen bearbeiten','timeline-settings','outline','settings')}`;}
 const end=r.rows.at(-1)?.month||c.start;return `<div class="goals-toolbar"><p>Ein Sparrahmen. Alle Wünsche zusammen.</p>${btn('Sparrahmen einstellen','timeline-settings','outline','settings')}</div><section class="goal-overview"><div><span>Maximal neu / Monat</span><strong>${euro(c.cap)}</strong></div><div><span>Mindestens frei</span><strong>${euro(c.minFree)}</strong></div><div><span>Vergleich bis</span><strong>${monthName(end,true)}</strong></div></section><p class="goal-context">Ab ${monthName(c.start)} · Bestehende Posten bleiben enthalten. Geschützte Bestände werden nicht als Zielkapital gezählt.</p>${!c.cap?'<div class="notice"><span>Lege Deinen gemeinsamen Sparrahmen fest, um zusätzliche Beträge automatisch auf Deine Wünsche zu verteilen.</span></div>':''}<div class="timeline-goals">${r.goals.map(({goal:g,reach,baseReach})=>{const target=g.deadline||reach||c.start,offset=Math.max(0,Math.min(35,(Number(target.slice(0,4))-Number(c.start.slice(0,4)))*12+Number(target.slice(5))-Number(c.start.slice(5))));return `<article class="timeline-goal"><div class="scenario-section-head"><div><span class="goal-kicker">${g.schedule?.timing==='fixed'?'Fester Termin':'Verschiebbar'} · Priorität ${g.schedule?.priority||50}</span><h3>${esc(g.title)}</h3></div><button class="textbtn" data-action="timeline-goal" data-id="${g.id}">Einordnen</button></div><div class="timeline-result"><strong>${!g.potId?'Topf fehlt':reach?monthName(reach):'Noch nicht gedeckt'}</strong><span>Preis ${euro(g.price)} · bisher ${baseReach?monthName(baseReach):'nicht im Zeitraum'}</span></div>${g.potId?`<label class="timeline-slider"><span>Wunschdatum ${g.deadline?monthName(g.deadline):'noch offen'}</span><input type="range" min="0" max="35" step="1" value="${offset}" data-timeline-goal="${g.id}" aria-label="Wunschmonat für ${esc(g.title)} verschieben"></label><div class="timeline-range"><span>${monthName(c.start,true)}</span><span>${monthName(end,true)}</span></div>`:`<p class="helper">Ordne diesem Wunsch unter „Wünsche“ einen Rücklagentopf zu.</p>`}</article>`;}).join('')||'<section class="goal-empty"><h2>Deine Wünsche fehlen noch</h2><p>Lege unter „Wünsche“ Ziele mit einem Preis und einem Rücklagentopf an.</p></section>'}</div>${r.warnings.length?`<details class="scenario-expand"><summary>${r.warnings.length} Hinweise zu Grenzen und Terminen</summary><ul class="scenario-warnings">${r.warnings.map(w=>`<li>${monthName(w.month)} · ${esc(w.text)}</li>`).join('')}</ul></details>`:''}<details class="scenario-expand"><summary>Monatliche Verteilung ansehen</summary><div class="scenario-table-wrap"><table class="scenario-table"><thead><tr><th>Monat</th><th>Neue Sparbeträge</th><th>Danach frei</th></tr></thead><tbody>${r.rows.map(row=>`<tr><th>${monthName(row.month)}</th><td class="timeline-allocation">${row.allocations.length?row.allocations.map(a=>esc(ctx.state.goals.find(g=>g.id===a.goalId).title)+': '+euro(a.amount)).join('<br>'):'–'}</td><td>${euro(row.remaining)}</td></tr>`).join('')}</tbody></table></div></details><p class="helper spaced">Die Berechnung reserviert Geld in getrennten Töpfen und kauft nichts automatisch. Frei gewordener Sparrahmen fließt zum nächsten Wunsch. Verschiebbare Wunschdaten sind Ziele, keine Zusagen. Spätere Bestandskorrekturen können frühere Einzahlungen überschreiben.</p>${r.lines.length?btn('Sparplan vor Übernahme prüfen','timeline-preview','primary','check'):''}`;}
 function preview(){const r=buildTimeline(ctx.state),c=cfg();form('Sparplan prüfen',`<p>${r.lines.length} einzelne Monatsraten von ${monthName(c.start)} bis ${monthName(r.rows.at(-1).month)}. ${c.replaceIds.length} freigegebene Sparraten / Serien werden ab dem Start beendet.</p>${c.replaceIds.length?`<ul class="scenario-preview">${c.replaceIds.map(id=>`<li><strong>Beenden: ${esc(ctx.state.items.find(i=>i.id===id)?.title||id)}</strong><span>Ab ${monthName(c.start)}</span></li>`).join('')}</ul>`:''}${r.warnings.length?'<p class="negative spaced">Es bestehen Hinweise zu Grenzen oder festen Terminen. Prüfe sie vor der Übernahme.</p>':''}<ul class="scenario-preview">${r.lines.map(l=>`<li><strong>${esc(l.title)} · ${euro(l.amount)}</strong><span>${monthName(l.start)}</span></li>`).join('')}</ul><p class="helper">Vorhandene Guthaben und tatsächliche Ausgaben ändern sich nicht. Du kannst diese Übernahme später zurücknehmen, solange betroffene Posten unverändert sind.</p>${foot('Sparplan verbindlich übernehmen')}`,()=>{if(ctx.persist(applyTimeline(ctx.state),'Sparplan übernommen'))close();});}
 function move(id,offset){if(cfg().applied)return;const n=structuredClone(ctx.state),g=n.goals.find(g=>g.id===id),date=shiftMonth(cfg().start,Number(offset));if(!g||!validMonth(date))return;g.deadline=date;ctx.persist(n,'Wunschdatum angepasst – Sparraten noch unverändert');}
 return {render,move,actions:{'timeline-settings':settings,'timeline-goal':el=>editGoal(el.dataset.id),'timeline-preview':preview,'timeline-undo':()=>{const revision=ctx.state.revision;ctx.confirmDialog('Sparplan zurücknehmen?','Die unveränderten Posten dieser Übernahme werden zurückgesetzt. Andere Änderungen bleiben erhalten.',()=>{if(revision!==ctx.state.revision)throw Error('Der Plan hat sich geändert. Bitte erneut öffnen.');if(ctx.persist(undoTimeline(ctx.state),'Sparplan zurückgenommen'))close();},'Zurücknehmen');}}};
}
